//! New offline journal derived from the original hash-pinned Extended PB cache.
//! It is independently regenerated by replay_calculated_retention; getters never
//! populate it. It is not a production event or a replacement canonical oracle.
use super::{binding, historical, BlockInput};
use anyhow::{ensure, Result};
pub const BYTES: &[u8] = include_bytes!("../../tests/fixtures/calculated-retention/journal.jsonl");
pub const SHA256: &str = "ebe020cca7b75e562cfe124eb074d275a2c8eb9f69f667099e98e9da3a88876d";
pub fn verify(raw: &[u8]) -> Result<Vec<BlockInput>> {
    ensure!(binding::sha(raw) == SHA256, "saved calculated journal raw hash differs");
    let text = std::str::from_utf8(raw)?;
    let inputs = text
        .lines()
        .map(serde_json::from_str::<BlockInput>)
        .collect::<std::result::Result<Vec<_>, _>>()?;
    ensure!(inputs.len() == 1024, "saved journal window differs");
    let compact = historical::original("lbp-replay")?;
    let mut previous = historical::parent()?;
    for (i, b) in inputs.iter().enumerate() {
        let c = &compact["blocks"][i];
        ensure!(
            b.at.number == previous.number + 1
                && b.at.parent_hash == Some(previous.hash)
                && b.at.timestamp >= previous.timestamp
                && b.at.producer_version == Some(5),
            "journal clock continuity"
        );
        ensure!(
            c["number"] == b.at.number
                && c["hash"] == format!("0x{}", hex::encode(b.at.hash))
                && c["timestamp"] == b.at.timestamp
                && c["source_sha256"] == b.source_sha256,
            "journal historical block binding"
        );
        previous = b.at.clone();
    }
    Ok(inputs)
}
